-- Raven Academy | Military Script V2
-- Optimized for Delta Executor
-- Safety: 99% (Clean Code)

local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "RAVEN ACADEMY | VIP",
   LoadingTitle = "جاري تشغيل سكربت الأكاديمية...",
   LoadingSubtitle = "بواسطة AI Assistant",
   ConfigurationSaving = {
      Enabled = true,
      FolderName = "RavenSafe"
   }
})

-- تبويب اللاعب (قوة بدنية)
local PlayerTab = Window:CreateTab("Movement (الحركة)", 4483345998)

PlayerTab:CreateSlider({
   Name = "WalkSpeed (السرعة)",
   Range = {16, 60},
   Increment = 1,
   Suffix = "Speed",
   CurrentValue = 16,
   Flag = "Slider1",
   Callback = function(Value)
      game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = Value
   end,
})

PlayerTab:CreateSlider({
   Name = "JumpPower (القفز)",
   Range = {50, 120},
   Increment = 1,
   Suffix = "Power",
   CurrentValue = 50,
   Flag = "Slider2",
   Callback = function(Value)
      game.Players.LocalPlayer.Character.Humanoid.JumpPower = Value
   end,
})

-- تبويب الرؤية (كشف الرتب واللاعبين)
local VisualsTab = Window:CreateTab("ESP (كشف الأماكن)", 4483345998)

VisualsTab:CreateButton({
   Name = "Enable ESP (تفعيل الكاشف)",
   Callback = function()
      -- كود كشف اللاعبين خلف الجدران
      loadstring(game:HttpGet('https://raw.githubusercontent.com/ic3w0lf22/Unnamed-ESP/master/Main.lua'))()
   end,
})

-- تبويب المهام العسكرية (أدوات الأكاديمية)
local AcademyTab = Window:CreateTab("Academy (أدوات الماب)", 4483345998)

AcademyTab:CreateButton({
   Name = "No Fog (إزالة الضباب)",
   Callback = function()
      game:GetService("Lighting").FogEnd = 100000
   end,
})

AcademyTab:CreateToggle({
   Name = "Infinite Jump (قفز مستمر)",
   CurrentValue = false,
   Flag = "InfJump",
   Callback = function(Value)
      _G.InfJump = Value
      game:GetService("UserInputService").JumpRequest:Connect(function()
         if _G.InfJump then
            game.Players.LocalPlayer.Character:FindFirstChildOfClass('Humanoid'):ChangeState("Jumping")
         end
      end)
   end,
})

AcademyTab:CreateButton({
   Name = "Fly Menu (قائمة الطيران)",
   Callback = function()
      loadstring(game:HttpGet("https://raw.githubusercontent.com/XNEOFF/FlyGuiV3/main/FlyGuiV3.lua"))()
   end,
})

Rayfield:Notify({
   Title = "تم التشغيل بنجاح",
   Content = "السكربت جاهز للاستخدام في أكاديمية ريفن",
   Duration = 5,
   Image = 4483345998,
})
